package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;import java.security.*;
public final class SkyTest {
 static String hash(ByteBuffer b)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");d.update(b);StringBuilder s=new StringBuilder();for(byte v:d.digest())s.append(String.format("%02x",v&255));return s.toString();}
 public static void main(String[] args)throws Exception{Path dir=Paths.get(args[0]);byte[] asset=Files.readAllBytes(dir.resolve("asset.bin"));int checks=0;for(String line:Files.readAllLines(dir.resolve("samples.tsv"))){String[] x=line.split("\t");int pair=Integer.parseInt(x[0]),mode=Integer.parseInt(x[1]);NativeSky a=new NativeSky(Files.readAllBytes(dir.resolve("pair-"+pair+"-old.bin"))),b=new NativeSky(Files.readAllBytes(dir.resolve("pair-"+pair+"-new.bin")));NativeSky.Sample s=a.sample(b,asset,Double.parseDouble(x[2]),mode);if(Math.abs(s.phase-Double.parseDouble(x[3]))>1e-10||Math.abs(s.weight-Double.parseDouble(x[4]))>1e-10||s.lowerOffset!=Integer.parseInt(x[5])||s.upperOffset!=Integer.parseInt(x[6])||s.exact!=x[7].equals("1")||!hash(s.lower()).equals(x[8])||!hash(s.upper()).equals(x[9])||!s.lower().isReadOnly())throw new AssertionError(line);checks++;}if(checks<100)throw new AssertionError("missing sky cases");NativeSky a=new NativeSky(Files.readAllBytes(dir.resolve("pair-0-old.bin"))),b=new NativeSky(Files.readAllBytes(dir.resolve("pair-0-new.bin")));int invalid=0;for(double alpha:new double[]{Double.NaN,-.1,1.1})try{a.sample(b,asset,alpha,1);throw new AssertionError("invalid alpha");}catch(IllegalArgumentException good){invalid++;}byte[] wrong=asset.clone();wrong[(int)(a.source-a.origin)]^=1;try{a.sample(b,wrong,.5,1);throw new AssertionError("invalid asset");}catch(IllegalArgumentException good){invalid++;}try{a.sample(b,asset,.5,2);throw new AssertionError("invalid mode");}catch(IllegalArgumentException good){invalid++;}NativeSky.Sample retained=a.sample(b,asset,.5,1);String before=hash(retained.lower());java.util.Arrays.fill(asset,(byte)0);if(!before.equals(hash(retained.lower())))throw new AssertionError("borrowed asset");System.out.println("PASS_SKY_C_PARITY samples="+checks+" invalid="+invalid+" immutable=true");}
}
